export function AsideElement({
  heading = "{{heading}}",
  body = "{{body}}",
  variant = "{{variant}}",
  accent = "{{accent}}",
}) {
  const wrap = variant === "sidebar"
    ? { borderLeft: `4px solid ${accent}` }
    : { border: "none", background: "transparent", borderTop: `2px solid ${accent}`, borderBottom: `2px solid ${accent}`, fontStyle: "italic" };
  return (
    <div style={{ display: "flex", gap: 20, width: 460, font: "15px/1.55 system-ui, sans-serif", color: "#241430" }}>
      <p style={{ flex: "1 1 auto", margin: 0, color: "#241430aa" }}>
        Main article text flows here, continuing for several paragraphs while this complementary note sits to the side.
      </p>
      <aside style={{ flex: "0 0 180px", background: "#FAF7F2", padding: "16px 18px", borderRadius: 10, ...wrap }}>
        <p style={{ margin: "0 0 6px", fontSize: 10, fontWeight: 700, letterSpacing: "0.08em", textTransform: "uppercase", color: accent }}>Aside</p>
        <h3 style={{ margin: "0 0 6px", fontSize: 15, fontWeight: 700 }}>{heading}</h3>
        <p style={{ margin: 0, fontSize: 13, color: "#241430cc" }}>{body}</p>
      </aside>
    </div>
  );
}
